  2593                  *linep++ = 0;
  2594                  while (c_isspace(*linep)) linep++;
  2595          }
  2596
  2597          if (*linep == '=') {
  2598                  // option with value, e.g. debug=y
  2599                  *linep++ = 0;
  2600                  while (c_isspace(*linep)) linep++;
  2601
  2602                  *val = linep;
  2603
  2604                  if (((quote = *linep) == '\"' || quote == '\'')) {
  2605                          char *src = linep + 1, *dst = linep, c;
  2606
  2607                          while ((c = *src) != quote && c) {
  2608                                  if (c == '\\' && src[1]) {
